class Solution:
    def integerBreak(self, n: int) -> int:
        if n <= 3:
            return n - 1
        q, r = divmod(n, 3)
        if r == 0:
            return 3 ** q
        if r == 1:
            return 3 ** (q - 1) * 4
        return 3 ** q * 2

code.C:
#include <stdio.h>
#include <stdlib.h>

int integerBreak(int n) {
    if (n <= 3) return n - 1;
    int q = n / 3, r = n % 3;
    long long p = 1;
    int threes = q - (r == 1 ? 1 : 0);
    for (int i = 0; i < threes; ++i) p *= 3;
    if (r == 0) return (int)p;
    if (r == 1) return (int)(p * 4);
    return (int)(p * 2);
}

